// HasPane applies the HasEdge predicate on the "pane" edge.
func HasPane() predicate.PaneTicketLink {
	return predicate.PaneTicketLink(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, PaneColumn),
			sqlgraph.Edge(sqlgraph.M2O, false, PaneTable, PaneColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPaneWith applies the HasEdge predicate on the "pane" edge with a given conditions (other predicates).
func HasPaneWith(preds ...predicate.WorkPane) predicate.PaneTicketLink {
	return predicate.PaneTicketLink(func(s *sql.Selector) {
		step := newPaneStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

